/*
 * prog22_snake_camel_convert
 *
 * Behaviour (as deduced from the obfuscated binary):
 *
 *   prog22_snake_camel_convert <mode> <string>
 *
 *   <mode> can be:
 *       "to_camel" – convert a snake_case identifier to camelCase.
 *       "to_snake" – convert a camelCase identifier to snake_case.
 *
 *   If the number of arguments is less than 3 the program prints:
 *       USAGE
 *
 *   If the mode string is not one of the two supported values the program
 *   prints:
 *       INVALID_MODE
 *
 *   After a successful conversion the resulting string is printed with
 *   `puts` (i.e. followed by a newline).  The original binary limits the
 *   output buffer to 1024 bytes; the implementation below uses a dynamic
 *   buffer that grows as needed, which is sufficient for the observable
 *   behaviour required by the task.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

/* Convert a snake_case string to camelCase.
 *   - The first word stays lower‑case.
 *   - Every subsequent word has its first character upper‑cased.
 *   - Underscores are removed.
 */
static char *to_camel(const char *src)
{
    size_t len = strlen(src);
    /* Allocate enough space (the result is never longer than the source). */
    char *dst = malloc(len + 1);
    if (!dst) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    size_t di = 0;          /* index in dst */
    int   capitalize = 0;  /* set after an underscore */

    for (size_t i = 0; i < len; ++i) {
        char ch = src[i];
        if (ch == '_') {
            capitalize = 1;               /* next character becomes upper case */
            continue;
        }
        if (capitalize) {
            dst[di++] = (char)toupper((unsigned char)ch);
            capitalize = 0;
        } else {
            dst[di++] = (char)tolower((unsigned char)ch);
        }
    }
    dst[di] = '\0';
    return dst;
}

/* Convert a camelCase string to snake_case.
 *   - An underscore is inserted before each upper‑case letter
 *     (except if it is the very first character).
 *   - Upper‑case letters are converted to lower‑case.
 */
static char *to_snake(const char *src)
{
    size_t len = strlen(src);
    /* In the worst case every character becomes "_x" → need at most 2*len. */
    char *dst = malloc(2 * len + 1);
    if (!dst) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    size_t di = 0;          /* index in dst */

    for (size_t i = 0; i < len; ++i) {
        char ch = src[i];
        if (isupper((unsigned char)ch)) {
            if (i != 0) {
                dst[di++] = '_';
            }
            dst[di++] = (char)tolower((unsigned char)ch);
        } else {
            dst[di++] = ch;
        }
    }
    dst[di] = '\0';
    return dst;
}

int main(int argc, char **argv)
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *mode = argv[1];
    const char *input = argv[2];
    char *result = NULL;

    if (strcmp(mode, "to_camel") == 0) {
        result = to_camel(input);
    } else if (strcmp(mode, "to_snake") == 0) {
        result = to_snake(input);
    } else {
        puts("INVALID_MODE");
        return 0;
    }

    puts(result);
    free(result);
    return 0;
}
